
(function(){
'use strict';
const PDFS={"1":"","2":"","3":"","4":"","5":"","6":"","7":"","7hp":"","8":"","c83":""};
let activeLine='1';
function openPdfKey(key){
  const b64=PDFS[key]; if(!b64){alert('PDF no disponible.');return;}
  try{
    const bin=atob(b64), arr=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);
    const url=URL.createObjectURL(new Blob([arr],{type:'application/pdf'}));
    window.open(url+'#zoom=page-width','_blank');
    setTimeout(()=>URL.revokeObjectURL(url),120000);
  }catch(e){alert('No se ha podido abrir el PDF en este navegador.');}
}
document.addEventListener('click',function(ev){
  const lineBtn=ev.target.closest && ev.target.closest('[data-line-schedule]');
  if(lineBtn)activeLine=String(lineBtn.dataset.lineSchedule||'1');
  if(ev.target.closest && ev.target.closest('#lineOfficialPdfBtn'))openPdfKey(activeLine);
  if(ev.target.closest && ev.target.closest('#lineOfficialRoutePdfBtn'))openOfficialRoutePdf();
  if(ev.target.closest && ev.target.closest('#schoolSelectedPdfBtn')){ var k=document.querySelector('.schoolRouteBtn.active')?.dataset.schoolRoute||'sanseb'; var schoolPdfs=window.V992_SCHOOL_PDFS||{}; try{ var b64=schoolPdfs[k]; if(!b64)throw new Error('PDF escolar no disponible'); var bin=atob(b64),arr=new Uint8Array(bin.length); for(var i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i); var url=URL.createObjectURL(new Blob([arr],{type:'application/pdf'})); window.open(url+'#zoom=page-width','_blank'); setTimeout(function(){URL.revokeObjectURL(url)},120000); }catch(e){alert('No se ha podido abrir el recorrido escolar seleccionado.');} }
},true);
})();
